from typing import Iterable, Dict

def analyze_frame(frame_bytes: bytes) -> Dict[str, float]:
    # placeholder for frequency / artifact / consistency features
    return {"artifact_score": 0.42, "temporal_score": 0.12}

def detect_stream(frames: Iterable[bytes]):
    for i, frame in enumerate(frames):
        scores = analyze_frame(frame)
        risk = 0.6 * scores["artifact_score"] + 0.4 * scores["temporal_score"]
        yield {"frame_index": i, "risk": risk}

type Scores = { artifact: number; temporal: number; compressionNoise: number }

export function calibratedRisk(s: Scores): number {
  const noisePenalty = Math.min(s.compressionNoise * 0.3, 0.2)
  return Math.max(0, 0.65 * s.artifact + 0.35 * s.temporal - noisePenalty)
}

export function isFlagged(risk: number, threshold = 0.72) {
  return risk >= threshold
}
